const priorResearchPosts: ReadonlyArray<ResearchPost> = [
  {slug:"research-nextjs-outsourcing-controls",title:"Research: controls for outsourced Next.js maintenance",excerpt:"What engineering teams should verify before assigning Next.js maintenance work.",published:"2026-08-07",body:["Scope the route, expected behavior, test command, and reviewer before assigning maintenance.","NIST SSDF: https://csrc.nist.gov/Projects/ssdf","Research takeaway: a contained ticket plus a named reviewer is a practical control."]},
  {slug:"research-react-developer-onboarding",title:"Research: onboarding patterns for outsourced React developers",excerpt:"Evidence-backed onboarding controls for a React work lane.",published:"2026-08-07",body:["A first React task should be small enough to review and include setup, acceptance checks, and rollback.","Google technical writing: https://developers.google.com/tech-writing","Research takeaway: test the setup guide with the person who will use it."]},
  {slug:"research-node-api-maintenance",title:"Research: evidence for outsourced Node.js API maintenance",excerpt:"How to define safe API maintenance work and its evidence trail.",published:"2026-08-07",body:["API maintenance needs a reproducible request, expected response, test data, and compatibility owner.","OWASP API Security: https://owasp.org/API-Security/","Research takeaway: require a request example and a negative-case test."]},
  {slug:"research-qa-automation-outsourcing",title:"Research: outsourcing QA automation without losing release control",excerpt:"A review of test ownership, evidence, and release boundaries.",published:"2026-08-07",body:["QA automation support is useful when test intent, environment, and failure triage rules are written first.","ISO software testing overview: https://www.iso.org/standard/45142.html","Research takeaway: the technical owner still decides whether a release ships."]},
  {slug:"research-database-cleanup-outsourcing",title:"Research: guardrails for outsourced database cleanup",excerpt:"A source-led review of reversible database maintenance controls.",published:"2026-08-07",body:["Database cleanup should begin with recovery, a bounded query, a dry run, and an owner-approved window.","OWASP SQL Injection Prevention: https://cheatsheetseries.owasp.org/cheatsheets/SQL_Injection_Prevention_Cheat_Sheet.html","Research takeaway: a reviewer should inspect the exact change."]},
  {slug:"research-legacy-code-maintenance",title:"Research: managing outsourced legacy application maintenance",excerpt:"How teams can make legacy maintenance observable and reviewable.",published:"2026-08-07",body:["Legacy work benefits from a baseline, logs, a focused ticket, and a test that captures the bug.","OpenTelemetry documentation: https://opentelemetry.io/docs/","Research takeaway: outsource a narrow maintenance slice first."]},
  {slug:"research-access-controls-programmers",title:"Research: access controls for outsourced programmers",excerpt:"A practical evidence review of identity, least privilege, and offboarding.",published:"2026-08-07",body:["Use an individual account, multifactor authentication where available, least privilege, and an owner for removal.","CISA Secure by Design: https://www.cisa.gov/securebydesign","Research takeaway: access is a managed lifecycle."]},
  {slug:"research-accessibility-testing-outsourcing",title:"Research: outsourced accessibility testing methods",excerpt:"A source-led checklist for useful web accessibility findings.",published:"2026-08-07",body:["Accessibility testing should combine automated checks with keyboard, focus, content, and assistive-technology review.","WCAG 2.2: https://www.w3.org/TR/WCAG22/","Research takeaway: findings should name route, impact, reproduction, and owner."]},
  {slug:"research-dependency-update-workflows",title:"Research: controlled outsourced dependency updates",excerpt:"How to separate routine package updates from risky upgrades.",published:"2026-08-07",body:["Dependency work needs an inventory, reason, release notes, tests, and rollback path.","OpenSSF Scorecard: https://scorecard.dev/","Research takeaway: review risk and evidence before calling an update routine."]},
  {slug:"research-remote-programmer-handoffs",title:"Research: remote handoffs for outsourced programming teams",excerpt:"Evidence-backed practices for decisions, blockers, and review windows.",published:"2026-08-07",body:["A useful handoff names the ticket, branch, checks, blocker, decision needed, and next action.","GitHub pull request reviews: https://docs.github.com/en/pull-requests/collaborating-with-pull-requests/reviewing-changes-in-pull-requests/about-pull-request-reviews","Research takeaway: written context makes review durable."]},
];
